// D74: equipment items (generated by `npm run import:equipment`, see docs/modules/equipment.md).
import type { Element, Vocation } from '../../types';

export type ItemSlot = 'helmet' | 'armor' | 'legs' | 'boots' | 'shield' | 'spellbook' | 'quiver' | 'amulet' | 'ring' | 'trinket';
export type ItemSkill = 'magic' | 'axe' | 'club' | 'sword' | 'fist' | 'distance' | 'shielding';

export interface ItemBonus {
  skills?: Partial<Record<ItemSkill, number>>;
  elementMl?: Partial<Record<'fire' | 'ice' | 'earth' | 'energy' | 'holy' | 'death' | 'healing', number>>;
  /** Resistance % per element (negative = weakness). */
  resist?: Partial<Record<Element, number>>;
  /** Percent values (2 = 2 %). */
  critChance?: number;
  lifeLeech?: number;
  manaLeech?: number;
  perfectShot?: { value: number; range: number };
}

export interface EquipmentItem {
  id: string;
  name: string;
  slot: ItemSlot;
  /** Undefined = every vocation. */
  vocations?: Vocation[];
  minLevel: number;
  armor?: number;
  /** Shields and spellbooks. */
  defense?: number;
  /** Item class (upgrade tier limit). */
  class?: number;
  imbuementSlots?: number;
  bonus?: ItemBonus;
}

export interface EquipmentFile {
  meta: { sources: string[]; items: number; issues: string[] };
  items: EquipmentItem[];
}
